const uid = () => 'ai_eng_' + Math.random().toString(36).substring(2, 11) + Date.now().toString(36);
const now = new Date().toISOString();

function makeTask(title, extraProps = {}) {
  return {
    id: uid(),
    title,
    status: 'not-started',
    priority: extraProps.priority || 'medium',
    notes: extraProps.notes || '',
    createdAt: now,
    ...extraProps
  };
}

function makeDay(dayNum, title, tasksList = [], extra = {}) {
  const allTasks = [];

  // If day 1, ensure the milestone task is present
  if (dayNum === 1) {
    allTasks.push(makeTask('AI Engineer Roadmap — Kickstart 336-day Deep AI/ML Engineering journey', { priority: 'high', type: 'milestone' }));
  }

  (tasksList || []).forEach((t, idx) => {
    allTasks.push(makeTask(typeof t === 'string' ? t : t.title, {
      type: idx === 0 ? 'learning' : (idx === tasksList.length - 1 ? 'practice' : 'hands-on'),
      priority: idx === 0 ? 'high' : 'medium'
    }));
  });

  return {
    id: uid(),
    dayNumber: dayNum,
    name: `Day ${dayNum} — ${title}`,
    mainTopic: title,
    status: 'not-started',
    date: '',
    tasks: allTasks,
    ...extra
  };
}

function makeWeek(weekNum, name, days = []) {
  return {
    id: uid(),
    weekNumber: weekNum,
    name: `Week ${weekNum} — ${name}`,
    days
  };
}

function makeMonth(monthNum, phaseName, name, weeks = []) {
  return {
    id: uid(),
    monthNumber: monthNum,
    phase: phaseName,
    name: `MONTH ${monthNum} — ${name}`,
    weeks
  };
}

function assignDates(months) {
  const start = new Date();
  start.setHours(0, 0, 0, 0);
  let dayOffset = 0;

  months.forEach((month) => {
    (month.weeks || []).forEach((week) => {
      (week.days || []).forEach((day) => {
        const d = new Date(start);
        d.setDate(d.getDate() + dayOffset);
        while (d.getDay() === 0 || d.getDay() === 6) {
          d.setDate(d.getDate() + 1);
          dayOffset++;
        }
        day.date = d.toISOString().split('T')[0];
        dayOffset++;
      });
    });
  });
  return months;
}

